mapper.select:


    inner join sys_user u on u.user_name = toutstrategy.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    toutstrategy.del_flag = '0'
     and toutstrategy.code like concat('%', #{code}, '%')
     and toutstrategy.flag = #{flag}
     and toutstrategy.name like concat('%', #{name}, '%')
     and toutstrategy.strategy_type = #{strategyType}
     and toutstrategy.priority = #{priority}


${params.dataScope}
